import React from 'react';
import {
    Card,
    CardContent,
    Typography,
    Box,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    TablePagination,
    Chip,
    Skeleton,
    IconButton,
    Tooltip,
} from '@mui/material';
import DownloadIcon from '@mui/icons-material/Download';
import { ForecastData } from '../../types';
import { formatNumber, formatDateTime } from '../../utils/formatters';

interface DataTableProps {
    data: ForecastData[];
    loading?: boolean;
    title?: string;
}

const DataTable: React.FC<DataTableProps> = ({
    data,
    loading = false,
    title = 'Forecast Data',
}) => {
    const [page, setPage] = React.useState(0);
    const [rowsPerPage, setRowsPerPage] = React.useState(10);

    const handleChangePage = (event: unknown, newPage: number) => {
        setPage(newPage);
    };

    const handleChangeRowsPerPage = (event: React.ChangeEvent<HTMLInputElement>) => {
        setRowsPerPage(parseInt(event.target.value, 10));
        setPage(0);
    };

    const handleExport = () => {
        // Create CSV content
        const headers = ['Timestamp', 'Predicted Stockpile (Kt)', 'Actual Stockpile (Kt)', 'Station'];
        const rows = data.map((row) => [
            row.timestamp,
            row.predicted_stockpile,
            row.actual_stockpile || 'N/A',
            row.station_name || 'N/A',
        ]);

        const csvContent = [
            headers.join(','),
            ...rows.map((row) => row.join(',')),
        ].join('\n');

        // Create and trigger download
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        const url = URL.createObjectURL(blob);
        link.setAttribute('href', url);
        link.setAttribute('download', `forecast_data_${new Date().toISOString()}.csv`);
        link.style.visibility = 'hidden';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    const getAccuracyColor = (predicted: number, actual?: number) => {
        if (!actual) return 'default';
        const diff = Math.abs(predicted - actual);
        const percentDiff = (diff / actual) * 100;

        if (percentDiff < 5) return 'success';
        if (percentDiff < 10) return 'warning';
        return 'error';
    };

    if (loading) {
        return (
            <Card>
                <CardContent>
                    <Skeleton variant="text" width="40%" height={32} />
                    <Skeleton variant="rectangular" width="100%" height={400} sx={{ mt: 2, borderRadius: 2 }} />
                </CardContent>
            </Card>
        );
    }

    const paginatedData = data.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage);

    return (
        <Card>
            <CardContent sx={{ p: 3 }}>
                <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
                    <Box>
                        <Typography variant="h5" fontWeight={700}>
                            {title}
                        </Typography>
                        <Typography variant="body2" color="text.secondary" mt={0.5}>
                            Detailed forecast predictions and actual values
                        </Typography>
                    </Box>
                    <Tooltip title="Export to CSV">
                        <IconButton
                            onClick={handleExport}
                            sx={{
                                backgroundColor: 'primary.main',
                                color: 'white',
                                '&:hover': {
                                    backgroundColor: 'primary.dark',
                                },
                            }}
                        >
                            <DownloadIcon />
                        </IconButton>
                    </Tooltip>
                </Box>

                <TableContainer>
                    <Table>
                        <TableHead>
                            <TableRow>
                                <TableCell>
                                    <Typography variant="body2" fontWeight={700}>
                                        Timestamp
                                    </Typography>
                                </TableCell>
                                <TableCell align="right">
                                    <Typography variant="body2" fontWeight={700}>
                                        Predicted (Kt)
                                    </Typography>
                                </TableCell>
                                <TableCell align="right">
                                    <Typography variant="body2" fontWeight={700}>
                                        Actual (Kt)
                                    </Typography>
                                </TableCell>
                                <TableCell align="center">
                                    <Typography variant="body2" fontWeight={700}>
                                        Accuracy
                                    </Typography>
                                </TableCell>
                                <TableCell>
                                    <Typography variant="body2" fontWeight={700}>
                                        Station
                                    </Typography>
                                </TableCell>
                            </TableRow>
                        </TableHead>
                        <TableBody>
                            {paginatedData.map((row, index) => (
                                <TableRow
                                    key={index}
                                    sx={{
                                        '&:hover': {
                                            backgroundColor: 'action.hover',
                                        },
                                    }}
                                >
                                    <TableCell>
                                        <Typography variant="body2" fontWeight={600}>
                                            {formatDateTime(row.timestamp)}
                                        </Typography>
                                    </TableCell>
                                    <TableCell align="right">
                                        <Typography variant="body2" fontWeight={600} color="primary.main">
                                            {formatNumber(row.predicted_stockpile)}
                                        </Typography>
                                    </TableCell>
                                    <TableCell align="right">
                                        <Typography variant="body2" fontWeight={600}>
                                            {row.actual_stockpile ? formatNumber(row.actual_stockpile) : 'N/A'}
                                        </Typography>
                                    </TableCell>
                                    <TableCell align="center">
                                        {row.actual_stockpile ? (
                                            <Chip
                                                label={`${((1 - Math.abs(row.predicted_stockpile - row.actual_stockpile) / row.actual_stockpile) * 100).toFixed(1)}%`}
                                                size="small"
                                                color={getAccuracyColor(row.predicted_stockpile, row.actual_stockpile) as any}
                                                sx={{ fontWeight: 700, minWidth: 60 }}
                                            />
                                        ) : (
                                            <Typography variant="body2" color="text.secondary">
                                                -
                                            </Typography>
                                        )}
                                    </TableCell>
                                    <TableCell>
                                        <Typography variant="body2">
                                            {row.station_name || 'N/A'}
                                        </Typography>
                                    </TableCell>
                                </TableRow>
                            ))}
                        </TableBody>
                    </Table>
                </TableContainer>

                <TablePagination
                    rowsPerPageOptions={[5, 10, 25, 50]}
                    component="div"
                    count={data.length}
                    rowsPerPage={rowsPerPage}
                    page={page}
                    onPageChange={handleChangePage}
                    onRowsPerPageChange={handleChangeRowsPerPage}
                    sx={{
                        borderTop: '1px solid',
                        borderColor: 'divider',
                        mt: 2,
                    }}
                />
            </CardContent>
        </Card>
    );
};

export default DataTable;
